        organizations.find((o) => o.id === org) ||
        (!org ? organizations[0] : null);
    if (!chosen) {
      deny();
      return;
    }
    org = chosen.id;
    const per = [
      ...(chosen.permissions || []),
      ...(formId
        ? chosen.scoped_forms?.find((f) => f.id === formId)?.permissions || []
